func:
msg.payload = {
    inspection_id: "INS-20261002-001",
    timestamp: new Date().toISOString(),

    overall_result: "OK",

    cam01: {
        slat: "OK",
        rib: "OK",
        pv_deviation: 34.4,
        max_deviation: 27.8
    },

    cam02: {
        bolt: "OK",
        pin: "OK"
    },

    cam03: {
        bolt: "OK",
        pin: "OK"
    }
};

return msg;

const d = msg.payload || {};
let defects = Array.isArray(d.defects) ? d.defects : [];

// Fallback jika payload simulasi/manual belum menyertakan array defects
if (defects.length === 0) {
    const c1 = d.cam01 || {};
    const c2 = d.cam02 || {};
    const c3 = d.cam03 || {};

    if (String(c1.rib || "").toUpperCase().includes("NG")) {
        defects.push({
            camera: "CAM-01",
            component: "Bilah Sirip (CAM-01)",
            component_short: "Rib",
            defect_type: "Rib Bengkok / Patah (Bending Deviation)",
            metrics: c1.max_deviation ? `Max Dev: ${c1.max_deviation}px` : "Defleksi melebihi batas",
            severity: "CRITICAL"
        });
    }

    if (String(c1.slat || "").toUpperCase().includes("NG")) {
        defects.push({
            camera: "CAM-01",
            component: "Plat Konveyor (CAM-01)",
            component_short: "Plat Slat",
            defect_type: "Deformasi / Celah Sambungan Renggang (Void)",
            metrics: c1.pv_deviation ? `Flatness PV: ${c1.pv_deviation}px` : "Celah / Kerataan melebihi ambang batas",
            severity: "CRITICAL"
        });
    }

    if (String(c2.bolt || "").toUpperCase().includes("NG")) {
        defects.push({
            camera: "CAM-02",
            component: "Baut Sisi Kanan (CAM-02)",
            component_short: "Bolt RH",
            defect_type: "Baut Kendur / Hilang (Bolt Abnormality)",
            metrics: String(c2.bolt),
            severity: "HIGH"
        });
    }
    if (String(c2.pin || "").toUpperCase().includes("NG")) {
        defects.push({
            camera: "CAM-02",
            component: "Pin Sisi Kanan (CAM-02)",
            component_short: "Pin RH",
            defect_type: "Pin Rantai Miring / Tergeser (Misalignment)",
            metrics: String(c2.pin),
            severity: "HIGH"
        });
    }

    if (String(c3.bolt || "").toUpperCase().includes("NG")) {
        defects.push({
            camera: "CAM-03",
            component: "Baut Sisi Kiri (CAM-03)",
            component_short: "Bolt LH",
            defect_type: "Baut Kendur / Hilang (Bolt Abnormality)",
            metrics: String(c3.bolt),
            severity: "HIGH"
        });
    }
    if (String(c3.pin || "").toUpperCase().includes("NG")) {
        defects.push({
            camera: "CAM-03",
            component: "Pin Sisi Kiri (CAM-03)",
            component_short: "Pin LH",
            defect_type: "Pin Rantai Miring / Tergeser (Misalignment)",
            metrics: String(c3.pin),
            severity: "HIGH"
        });
    }
}

// Fallback jika tetap kosong tetapi overall_result NG
if (defects.length === 0) {
    defects.push({
        camera: "SYSTEM",
        component: "Inspeksi Visual Konveyor",
        component_short: "Anomali",
        defect_type: "Abnormalitas Terdeteksi Pada Jalur Konveyor",
        metrics: "Status Sistem: NG",
        severity: "MEDIUM"
    });
}

const traceCode = String(d.inspection_id || "-");
const evidenceUrl = d.evidence_url || `http://localhost:5173/?trace=${encodeURIComponent(traceCode)}`;
const count = defects.length;
const isMulti = count > 1;

let headerTitle = "";
let subTitle = "";

if (isMulti) {
    const names = defects.map(x => x.component_short || x.component).join(" + ");
    headerTitle = `🚨 MULTI-ABNORMALITAS (${count} KOMPONEN NG)`;
    subTitle = `Terdeteksi ${count} komponen mengalami kerusakan/anomali (${names}). Tindakan korektif segera diperlukan.`;
} else {
    headerTitle = `⚠️ ABNORMALITAS: ${defects[0].component.toUpperCase()}`;
    subTitle = `Terdeteksi 1 komponen mengalami anomali spesifik dan memerlukan atensi teknisi lapangan.`;
}

const cardBody = [
    // Header Banner Merah (Attention)
    {
        type: "Container",
        style: "attention",
        bleed: true,
        items: [
            {
                type: "TextBlock",
                text: headerTitle,
                weight: "Bolder",
                size: "Large",
                color: "Light",
                wrap: true
            },
            {
                type: "TextBlock",
                text: subTitle,
                size: "Small",
                color: "Light",
                wrap: true
            }
        ]
    },
    // Meta Information
    {
        type: "FactSet",
        spacing: "Medium",
        facts: [
            {
                title: "ID Inspeksi",
                value: traceCode
            },
            {
                title: "Waktu Deteksi",
                value: String(d.timestamp || new Date().toLocaleString("id-ID"))
            },
            {
                title: "Jumlah Cacat",
                value: `${count} Komponen Bermasalah`
            }
        ]
    },
    // Section Header
    {
        type: "TextBlock",
        text: "DAFTAR KOMPONEN ABNORMAL (NG):",
        weight: "Bolder",
        size: "Medium",
        spacing: "Medium"
    }
];

// Masukkan HANYA komponen yang benar-benar NG ke dalam Card Body
defects.forEach((def, index) => {
    let icon = "⚠️";
    if (def.camera === "CAM-01") {
        icon = (def.component_short && def.component_short.toLowerCase().includes("rib")) ? "📐" : "📏";
    } else if (def.camera === "CAM-02" || def.camera === "CAM-03") {
        icon = (def.component_short && def.component_short.toLowerCase().includes("pin")) ? "📍" : "🔩";
    }

    const itemElements = [
        {
            type: "TextBlock",
            text: `**${index + 1}. ${def.component}**`,
            weight: "Bolder",
            size: "Medium",
            color: "Attention",
            wrap: true
        },
        {
            type: "TextBlock",
            text: `Masalah: **${def.defect_type}**`,
            size: "Default",
            spacing: "None",
            wrap: true
        }
    ];

    if (def.metrics) {
        itemElements.push({
            type: "TextBlock",
            text: `📊 *Detail Parameter: ${def.metrics}*`,
            size: "Small",
            isSubtle: true,
            spacing: "None",
            wrap: true
        });
    }

    cardBody.push({
        type: "Container",
        style: "emphasis",
        spacing: "Small",
        items: [
            {
                type: "ColumnSet",
                columns: [
                    {
                        type: "Column",
                        width: "auto",
                        items: [
                            {
                                type: "TextBlock",
                                text: icon,
                                size: "Medium"
                            }
                        ]
                    },
                    {
                        type: "Column",
                        width: "stretch",
                        items: itemElements
                    }
                ]
            }
        ]
    });
});

// Footer Info & Direct Link
cardBody.push(
    {
        type: "TextBlock",
        text: `👉 [**🔍 KLIK DI SINI UNTUK BUKA DETAIL DI DASHBOARD**](${evidenceUrl})`,
        weight: "Bolder",
        color: "Accent",
        spacing: "Large",
        wrap: true
    },
    {
        type: "TextBlock",
        text: "Sistem Inspeksi Otomatis AI • Conveyor Slat & Rib Metrology",
        isSubtle: true,
        size: "Small",
        spacing: "Small"
    }
);

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    type: "message",
    attachments: [
        {
            contentType: "application/vnd.microsoft.card.adaptive",
            content: {
                "$schema": "http://adaptivecards.io/schemas/adaptive-card.json",
                type: "AdaptiveCard",
                version: "1.2",
                body: cardBody,
                actions: [
                    {
                        type: "Action.OpenUrl",
                        title: "🔍 Buka Detail Anomali di Web Dashboard",
                        url: evidenceUrl
                    }
                ]
            }
        }
    ]
};

return msg;

const inspection = msg.payload;

node.warn("PAYLOAD DITERIMA:");
node.warn(inspection);

// Output 1 → HTTP Response
const responseMsg = {
    ...msg,
    payload: {
        status: "received",
        inspection_id: inspection.inspection_id || null,
        overall_result: inspection.overall_result || null
    }
};

// Output 2 → proses inspeksi → Switch → Teams
const processingMsg = {
    ...msg,
    payload: inspection
};

// Output 1 = response
// Output 2 = processing
return [responseMsg, processingMsg];
